mapper.update:
update review
set
    is_deleted = 1
where review_id = #{reviewId}
    and user_id = #{userId}
    and is_deleted = false

update company_review
set
    communication_rate = #{communicationRate}, price_rate = #{priceRate},
    result_rate = #{resultRate}, schedule_rate = #{scheduleRate},
    structure_type = #{structureType}, area_pyeong = #{areaPyeong}, construction_field = #{constructionField}
where review_id = #{reviewId}
